import express from 'express';
const app = express();
app.get('/api/tasks', (_req, res) => res.status(200).json({ items: [] }));
app.post('/api/tasks', (_req, res) => res.status(201).json({ id: 1 }));
app.delete('/api/tasks/:id', (_req, res) => res.status(204).end());
app.listen(3000);
